from .vocab import recipe as _r


def hi(slug, name, typ, servings, total, description, steps, ingredients, popularity=76, **kw):
    prep = min(10, total // 2)
    return _r(slug, name, typ, servings, prep, total - prep, description, steps, ingredients, popularity,
              cuisine="haftaici", tags="haftaici", **kw)


